def calculate_total_with_discount(subtotal, discount_rate=0.10, threshold=100):
    if subtotal > threshold:
        total = subtotal * (1 - discount_rate)
    else:
        total = subtotal
    return total

item_prices = [20, 30, 60]
total = calculate_total_with_discount(sum(item_prices))
print(total)

